#nullable enable

readonly struct Score
{
    public int Value { get; }
    public Score(int value) => Value = value;
}

static int Max(in Score first, in Score second) =>
    first.Value >= second.Value ? first.Value : second.Value;

Score a = new(88);
Score b = new(93);
string? optionalNote = null;
Console.WriteLine(Max(in a, in b));
Console.WriteLine(optionalNote?.Length ?? 0);

