public interface IScorer<TSelf> where TSelf : IScorer<TSelf>
{
    static abstract TSelf FromScore(int value);
    int Value { get; }
}

public readonly record struct Score(int Value) : IScorer<Score>
{
    public static Score FromScore(int value) => new(value);
}

static T CreatePerfect<T>() where T : IScorer<T> => T.FromScore(100);
Console.WriteLine(CreatePerfect<Score>().Value);

