public interface IProgressStore
{
    Task SaveAsync(int score, CancellationToken token);
}

public sealed class AcademyService
{
    private readonly IProgressStore _store;
    public AcademyService(IProgressStore store) => _store = store;

    public Task SavePassingScoreAsync(int score, CancellationToken token)
    {
        if (score < 80) throw new InvalidOperationException("Score is not passing.");
        return _store.SaveAsync(score, token);
    }
}

